-- Oxy Implant catalogue (PSK-MDK and MD EXT) replaces the sample brands from 0008.
-- Source: docs/catalog/oxy-catalog.csv, drafted from the official Oxy catalogues
-- (PSK-MDK Rev. 02-23-EN, MD EXT Rev. 00-22-ES-M) and approved on 2026-10-03.

-- The sample brands are deactivated, not deleted: an admin can reactivate them under Inventory → Products.
update public.products set active = false
where is_sample and active
  and brand in ('Straumann', 'Nobel Biocare', 'Neodent', 'MIS', 'Osstem', 'Geistlich');

insert into public.products (type, brand, system, platform, diameter_mm, length_mm, ref_code, description)
